"""SCMOVS update: auto-close elections, new Add User form (Student role, address, birthday, contact no.),
Super Admin can vote and work like an officer.

BEFORE YOU START: make a backup of your database (see my earlier backup steps).

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_big_update.py
  3. When it asks, answer  y  to update the database (it adds the new columns; safe to run twice).
  4. Restart the app (python run.py) and press Ctrl+F5 in the browser.

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
It does NOT touch .env, run.py, requirements.txt or config.py.
"""
import base64
import os
import shutil
import subprocess
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/__init__.py': "",
    'app/admin/routes.py': "",
    'app/admin/services.py': "",
    'app/elections/auto_close.py': "",
    'app/elections/services.py': "",
    'app/finance/routes.py': "",
    'app/finance/services.py': "",
    'app/locations.py': "",
    'app/profile/routes.py': "",
    'app/proposals/routes.py': "",
    'app/proposals/services.py': "",
    'app/students/routes.py': "",
    'app/students/services.py': "",
    'app/validators.py': "",
    'app/voting/routes.py': "",
    'app/voting/services.py': "",
    'close_due_elections.py': "",
    'database/apply_migration_006.py': "",
    'database/migration_006.py': "",
    'database/schema.sql': "",
    'static/js/form_rules.js': "",
    'templates/components/modal.html': "",
    'templates/layouts/app_layout.html': "",
    'templates/profile.html': "",
    'templates/profile/_edit_modal.html': "",
    'templates/students/_form_modal.html': "",
    'templates/super_admin/users/_form_modal.html': "",
    'templates/voting/list.html': "",
    'tests/helpers.py': "",
    'tests/run_all.sh': "",
    'tests/test_auto_close.py': "",
    'tests/test_modals_more.py': "",
    'tests/test_new_features.py': "",
    'tests/test_users.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print(f"\n{len(FILES)} files written.")

    print("\nThe new version needs new database columns (address, birthday, contact number) and a change that lets")
    print("the Super Admin vote. Nothing is deleted and existing votes are kept. Have you backed up your database?")
    answer = input("Update the database now? [y/n]: ").strip().lower()
    if answer in ("y", "yes"):
        result = subprocess.run([sys.executable, os.path.join(ROOT, "database", "apply_migration_006.py")], cwd=ROOT)
        if result.returncode != 0:
            print("\nThe database update FAILED (see the message above). The app will not work until it succeeds.")
            print("Send me the message and I will help. You can retry with:  python database/apply_migration_006.py")
            sys.exit(result.returncode)
    else:
        print("\nSkipped. Before starting the app, run:   python database/apply_migration_006.py")
    print("\nDone. Restart the app (python run.py) and press Ctrl+F5 in the browser.")


if __name__ == "__main__":
    main()
